def _load(data, digest):
    raw = zlib.decompress(base64.b85decode(data))
    if hashlib.sha256(raw).hexdigest() != digest:
        raise ValueError('Massive placement metadata changed')
    return json.loads(raw)

def load_plan():
    return _load(_PLAN_DATA, PLAN_SHA256)

def load_hashes():
    return _load(_HASHES_DATA, HASHES_SHA256)['files']
